script:
const result = bh.local.claimResult || [];

if (!Array.isArray(result) || result.length === 0) {

    bh.local.claimFound = false;

    bh.local.responseStatus = 404;

    bh.local.response = {
        success: false,
        message: "Claim not found",
        claimId: bh.local.claimId
    };

}
else {
const data = result[0];

bh.local.claimFound = true;

bh.local.claim = {
    id: Number(data.id),
    claimNumber: data.claim_number,
    policyId: Number(data.policy_id),
    claimantType: data.claimant_type,
    lossDateTime: data.loss_date_time,
    lossLocation: data.loss_location,
    lossType: data.loss_type,
    lossDescription: data.loss_description,
    driverName: data.driver_name,
    driverLicenceStatus: data.driver_licence_status,
    policeReportAvailable: data.police_report_available,
    policeReportReference: data.police_report_reference,
    estimatedLossAmount: data.estimated_loss_amount,
    currency: data.currency,
    vehicleDrivable: data.vehicle_drivable,
    thirdPartyInvolved: data.third_party_involved,
    injuryInvolved: data.injury_involved,
    preferredContactMethod: data.preferred_contact_method,
    preferredContactValue: data.preferred_contact_value,
    status: data.status,
    createdBy: data.created_by,
    createdAt: data.created_at,
    updatedAt: data.updated_at
};

bh.local.policy = {
    id: Number(data.policy_id),
    policyNumber: data.policy_number,
    customerId: data.customer_id,
    policyStatus: data.policy_status,
    policyStartDate: data.policy_start_date,
    policyEndDate: data.policy_end_date,
    insuredName: data.insured_name,
    vehicleRegistration: data.vehicle_registration,
    vehicleMake: data.vehicle_make,
    vehicleModel: data.vehicle_model,
    vehicleYear: data.vehicle_year,
    coverageType: data.coverage_type,
    coveredPerils: data.covered_perils,
    excessAmount: data.excess_amount,
    sumInsured: data.sum_insured
};

}

bh.local.responseStatus = 200;

bh.local.response = {
    success: true,
    claim: bh.local.claim,
    policy: bh.local.policy,
    evidence: [],
    decision: null
};

const body = bh.input.body || {};

bh.local.claimId = Number(body.claimId || 0);
bh.local.decision = String(body.decision || "").trim();
bh.local.status = String(body.status || "").trim();
bh.local.decisionSource =
    String(body.decisionSource || "BPM").trim();
bh.local.decisionRole =
    String(body.decisionRole || "SYSTEM").trim();
bh.local.comments =
    String(body.comments || "").trim();
bh.local.correlationId =
    String(body.correlationId || "").trim();

bh.local.valid = true;
bh.local.error = "";

if (!bh.local.claimId) {
    bh.local.valid = false;
    bh.local.error = "claimId is required";
}

if (!bh.local.decision) {
    bh.local.valid = false;
    bh.local.error = "decision is required";
}

if (!bh.local.status) {
    bh.local.valid = false;
    bh.local.error = "status is required";
}
bh.local.claimSql = `
    SELECT
        id,
        claim_number,
        status
    FROM public.claims
    WHERE id = $1
    LIMIT 1
`;

bh.local.claimSqlParams = [
    bh.local.claimId
];

/* =========================================================
   CLAIM LOOKUP RESPONSE
   ========================================================= */

console.log("========== CLAIM LOOKUP RESPONSE ==========");

console.log(
    "Raw claimResponse:",
    JSON.stringify(
        bh.local.claimResponse,
        null,
        2
    )
);


/* =========================================================
   NORMALIZE SQL RESULT
   ========================================================= */

let rows = bh.local.claimResponse;


/*
 * SQL node may return:
 *
 * 1. Array
 * 2. { rows: [...] }
 * 3. { payload: [...] }
 * 4. { data: [...] }
 */

if (Array.isArray(rows)) {

    rows = rows;

} else if (
    rows &&
    Array.isArray(rows.rows)
) {

    rows = rows.rows;

} else if (
    rows &&
    rows.payload &&
    Array.isArray(rows.payload)
) {

    rows = rows.payload;

} else if (
    rows &&
    rows.data &&
    Array.isArray(rows.data)
) {

    rows = rows.data;

} else {

    rows = [];
}


/* =========================================================
   CLAIM NOT FOUND
   ========================================================= */

if (rows.length === 0) {

    bh.local.claimFound = false;

    bh.local.claimUpdateSuccess = false;

    bh.local.auditInsertSuccess = false;

    bh.local.responseStatus = 404;

    bh.local.response = {

        success: false,

        message:
            "Claim not found",

        claimId:
            Number(bh.local.claimId)
    };

    console.error(
        "Claim not found. Claim ID:",
        bh.local.claimId
    );

} else {

    /* =====================================================
       CLAIM FOUND
       ===================================================== */

    bh.local.claimFound = true;

    bh.local.claimNumber =
        String(
            rows[0].claim_number ||
            rows[0].claimNumber ||
            ""
        );

    bh.local.oldStatus =
        String(
            rows[0].status ||
            ""
        );


    /* =====================================================
       PREPARE UPDATE SQL
       ===================================================== */

    const esc = (value) =>
        String(
            value == null ? "" : value
        ).replace(/'/g, "''");


    bh.local.updateSql =
        "UPDATE public.claims " +
        "SET status = '" +
        esc(bh.local.status) +
        "', updated_at = CURRENT_TIMESTAMP " +
        "WHERE id = " +
        Number(bh.local.claimId) +
        ";";


    /* =====================================================
       PREPARE AUDIT SQL
       ===================================================== */

    bh.local.auditSql =
        "INSERT INTO public.claim_audit (" +
        "claim_id, " +
        "event_type, " +
        "user_id, " +
        "user_role, " +
        "action, " +
        "comments, " +
        "old_status, " +
        "new_status, " +
        "correlation_id, " +
        "integration_name, " +
        "integration_status" +
        ") VALUES (" +

        Number(bh.local.claimId) +
        ", " +

        "'CLAIM_DECISION', " +

        "'" +
        esc(bh.local.decisionSource) +
        "', " +

        "'" +
        esc(bh.local.decisionRole) +
        "', " +

        "'" +
        esc(bh.local.decision) +
        "', " +

        "'" +
        esc(bh.local.comments) +
        "', " +

        "'" +
        esc(bh.local.oldStatus) +
        "', " +

        "'" +
        esc(bh.local.status) +
        "', " +

        "'" +
        esc(bh.local.correlationId) +
        "', " +

        "'CLAIMS_DECISION_API', " +

        "'SUCCESS'" +

        ");";


    console.log(
        "Claim found:",
        bh.local.claimFound
    );

    console.log(
        "Claim number:",
        bh.local.claimNumber
    );

    console.log(
        "Old status:",
        bh.local.oldStatus
    );

    console.log(
        "Update SQL:",
        bh.local.updateSql
    );

    console.log(
        "Audit SQL:",
        bh.local.auditSql
    );
}


console.log(
    "=========================================="
);

/* =========================================================
   AUDIT INSERT SUCCESS
   ========================================================= */

console.log(
    "========== CLAIM AUDIT =========="
);

console.log(
    "Audit SQL:",
    bh.local.auditSql
);

console.log(
    "Claim ID:",
    bh.local.claimId
);

console.log(
    "Correlation ID:",
    bh.local.correlationId
);


/*
 * SQL node completed without throwing an error.
 * Therefore audit INSERT was successful.
 */

bh.local.auditInsertSuccess = true;


console.log(
    "auditInsertSuccess:",
    bh.local.auditInsertSuccess
);

console.log(
    "================================="
);
/* =========================================================
   FINAL CLAIM DECISION RESPONSE
   ========================================================= */

console.log("========== FINAL CLAIM DECISION RESPONSE ==========");

console.log(
    "claimFound:",
    bh.local.claimFound
);

console.log(
    "claimUpdateSuccess:",
    bh.local.claimUpdateSuccess
);

console.log(
    "auditInsertSuccess:",
    bh.local.auditInsertSuccess
);


/* =========================================================
   NORMALIZE SUCCESS FLAGS
   ========================================================= */

const claimFound =
    bh.local.claimFound === true ||
    bh.local.claimFound === "true";

const claimUpdateSuccess =
    bh.local.claimUpdateSuccess === true ||
    bh.local.claimUpdateSuccess === "true";

const auditInsertSuccess =
    bh.local.auditInsertSuccess === true ||
    bh.local.auditInsertSuccess === "true";


/* =========================================================
   FINAL SUCCESS
   ========================================================= */

if (
    claimFound &&
    claimUpdateSuccess &&
    auditInsertSuccess
) {

    bh.local.responseStatus = 200;

    bh.local.response = {

        success: true,

        message:
            "Claim decision updated successfully.",

        claimId:
            Number(bh.local.claimId),

        claimNumber:
            bh.local.claimNumber || "",

        decision:
            bh.local.decision || "",

        status:
            bh.local.status || "",

        oldStatus:
            bh.local.oldStatus || "",

        newStatus:
            bh.local.status || "",

        auditRecorded:
            true,

        correlationId:
            bh.local.correlationId || ""
    };

    console.log(
        "CLAIM DECISION SUCCESS"
    );

} else {

    bh.local.responseStatus = 500;

    bh.local.response = {

        success: false,

        message:
            "Claim decision update failed.",

        claimId:
            Number(bh.local.claimId),

        claimNumber:
            bh.local.claimNumber || "",

        decision:
            bh.local.decision || "",

        status:
            bh.local.status || "",

        auditRecorded:
            auditInsertSuccess,

        correlationId:
            bh.local.correlationId || "",

        details: {

            claimFound:
                claimFound,

            claimUpdateSuccess:
                claimUpdateSuccess,

            auditInsertSuccess:
                auditInsertSuccess
        }
    };

    console.error(
        "CLAIM DECISION FAILED"
    );
}


console.log(
    "Final response:",
    JSON.stringify(
        bh.local.response,
        null,
        2
    )
);

console.log(
    "Final response status:",
    bh.local.responseStatus
);

console.log(
    "=================================================="
);

const body = bh.input.body || {};

const requiredFields = [
    "policyId",
    "lossDateTime",
    "lossLocation",
    "lossType",
    "lossDescription",
    "estimatedLossAmount",
    "currency"
];

const missingFields = requiredFields.filter(
    field =>
        body[field] === undefined ||
        body[field] === null ||
        body[field] === ""
);

if (missingFields.length > 0) {

    bh.local.isValid = false;

    bh.local.validationErrors = missingFields;

    bh.local.responseStatus = 400;

    bh.local.response = {
        success: false,
        message: "Required fields are missing",
        missingFields: missingFields
    };

}else{

/*
 * Prepare claim values
 */

bh.local.isValid = true;

bh.local.policyId = body.policyId;
bh.local.claimantType = body.claimantType || "POLICYHOLDER";

bh.local.lossDateTime = body.lossDateTime;
bh.local.lossLocation = body.lossLocation;
bh.local.lossType = body.lossType;
bh.local.lossDescription = body.lossDescription;

bh.local.driverName = body.driverName || null;
bh.local.driverLicenceStatus =
    body.driverLicenceStatus || null;

bh.local.policeReportAvailable =
    body.policeReportAvailable ?? false;

bh.local.policeReportReference =
    body.policeReportReference || null;

bh.local.estimatedLossAmount =
    body.estimatedLossAmount;

bh.local.currency =
    body.currency || "INR";

bh.local.vehicleDrivable =
    body.vehicleDrivable ?? null;

bh.local.thirdPartyInvolved =
    body.thirdPartyInvolved ?? false;

bh.local.injuryInvolved =
    body.injuryInvolved ?? false;

bh.local.preferredContactMethod =
    body.preferredContactMethod || null;

bh.local.preferredContactValue =
    body.preferredContactValue || null;

bh.local.createdBy =
    body.createdBy || "FNOL_USER";


/*
 * Prepare Policy Lookup SQL
 */

bh.local.policySql = `
    SELECT
        id,
        policy_number,
        customer_id,
        policy_status,
        policy_start_date,
        policy_end_date,
        insured_name,
        vehicle_registration,
        vehicle_make,
        vehicle_model,
        vehicle_year,
        coverage_type,
        covered_perils,
        excess_amount,
        sum_insured,
        currency
    FROM policy_master
    WHERE id = $1
    LIMIT 1
`;

bh.local.policySqlParams = [
    bh.local.policyId
];
}

const policyResult = bh.local.policyResult || [];
console.log(
    "FULL POLICY OBJECT:",
    JSON.stringify(
        bh.local.policyResult,
        null,
        2
    )
);
if (!Array.isArray(policyResult) || policyResult.length === 0) {
    bh.local.policyFound = false;

    bh.local.responseStatus = 404;

    bh.local.response = {
        success: false,
        message: "Policy not found",
        policyId: bh.local.policyId
    };

}else{

const policy = policyResult[0];

bh.local.policyFound = true;
bh.local.policy = policy;

// Keep the verified policy values available for the claim INSERT
bh.local.verifiedPolicyId = policy.id;
bh.local.policyNumber = policy.policy_number;
bh.local.policyStatus = policy.policy_status;
}

const body = bh.input.body || {};

const evidence = body.evidence || [];

bh.local.evidence = evidence;

bh.local.hasEvidence =
    Array.isArray(evidence) &&
    evidence.length > 0;

console.log("Evidence received:", evidence);
console.log("Has evidence:", bh.local.hasEvidence);

const claimResult = bh.local.claimResult || [];

console.log("========== CLAIM RESULT ==========");
console.log(claimResult);

if (!Array.isArray(claimResult) || claimResult.length === 0) {

    bh.local.claimCreated = false;

    bh.local.responseStatus = 500;

    bh.local.response = {
        success: false,
        message: "Claim creation failed. No claim record was returned."
    };

} else {

    const claim = claimResult[0];

    bh.local.claimCreated = true;

    bh.local.claim = claim;

    bh.local.claimId = claim.id;
    bh.local.claimNumber = claim.claim_number;
    bh.local.claimPolicyId = claim.policy_id;
    bh.local.claimStatus = claim.status;
    bh.local.claimCreatedAt = claim.created_at;

    console.log("Claim created successfully");
    console.log("Claim ID:", bh.local.claimId);
    console.log("Claim Number:", bh.local.claimNumber);
    console.log("Policy ID:", bh.local.claimPolicyId);
    console.log("Claim Status:", bh.local.claimStatus);
}

/* =========================================================
   CASE CREATION RESPONSE
   ========================================================= */

const rawCaseResponse =
    bh.local.caseCreationResponse || {};


const caseResponse =
    rawCaseResponse &&
    rawCaseResponse.payload &&
    typeof rawCaseResponse.payload === "object"
        ? rawCaseResponse.payload
        : rawCaseResponse;


bh.local.caseCreationResponse =
    caseResponse;


/* =========================================================
   EXTRACT CASE ID
   ========================================================= */

bh.local.caseId =
    caseResponse.caseId ||
    caseResponse.id ||
    caseResponse.caseInstanceId ||
    (
        caseResponse.case &&
        (
            caseResponse.case.caseId ||
            caseResponse.case.id ||
            caseResponse.case.caseInstanceId
        )
    ) ||
    null;


/* =========================================================
   DETERMINE SUCCESS
   ========================================================= */

bh.local.caseCreated =
    !!(
        bh.local.caseId ||
        caseResponse.success === true ||
        caseResponse.status === "SUCCESS"
    );


console.log(
    "========== CASE CREATION RESPONSE =========="
);

console.log(
    JSON.stringify(
        caseResponse,
        null,
        2
    )
);

console.log(
    "Case ID:",
    bh.local.caseId
);

console.log(
    "Case Created:",
    bh.local.caseCreated
);

console.log(
    "============================================="
);

const evidence = bh.local.evidence || [];

bh.local.dmsFiles = evidence.map(file => ({
    claimId: bh.local.claimId,
    documentType: file.documentType,
    fileName: file.fileName || file.name,
    mimeType: file.mimeType || file.type,
    fileSize: file.fileSize || file.size,
    file: file.file
}));

bh.local.dmsFileCount = bh.local.dmsFiles.length;

console.log("DMS files prepared:", bh.local.dmsFiles);

const rawTokenResponse =
    bh.local.caseTokenResponse || {};


const tokenResponse =
    rawTokenResponse &&
    rawTokenResponse.payload &&
    typeof rawTokenResponse.payload === "object"
        ? rawTokenResponse.payload
        : rawTokenResponse;


console.log(
    "========== CASE TOKEN RESPONSE =========="
);

console.log(
    JSON.stringify(
        tokenResponse,
        null,
        2
    )
);


/* =========================================================
   VALIDATE TOKEN
   ========================================================= */

if (
    !tokenResponse.access_token ||
    typeof tokenResponse.access_token !== "string" ||
    !tokenResponse.access_token.trim()
) {

    bh.local.caseTokenSuccess = false;

    bh.local.caseAccessToken = "";

    bh.local.caseCreationReady = false;

    console.error(
        "Case Service authentication failed: access token missing."
    );

} else {

    bh.local.caseTokenSuccess = true;

    bh.local.caseAccessToken =
        tokenResponse.access_token.trim();

    bh.local.caseCreationReady = true;

    console.log(
        "Case Service authentication successful."
    );

    console.log(
        "Access token received:",
        true
    );
}


/* =========================================================
   DEBUG
   ========================================================= */

console.log(
    "Case Token Success:",
    bh.local.caseTokenSuccess
);

console.log(
    "Case Creation Ready:",
    bh.local.caseCreationReady
);

console.log(
    "=========================================="
);

const CLIENT_ID =
    bh.system.environment.CASE_SERVICE_CLIENT_ID;

const CLIENT_SECRET =
    bh.system.environment.CASE_SERVICE_CLIENT_SECRET;


/* =========================================================
   TOKEN URL
   ========================================================= */

bh.local.caseTokenUrl =
    "https://ids-ctr-pt.neutrinos-apps.com/token";


/* =========================================================
   TOKEN BODY
   ========================================================= */

bh.local.caseTokenBody =
    "grant_type=client_credentials&client_id=" +
    encodeURIComponent(CLIENT_ID) +
    "&client_secret=" +
    encodeURIComponent(CLIENT_SECRET);


/* =========================================================
   TOKEN HEADERS
   ========================================================= */

bh.local.caseTokenHeaders = {

    "Content-Type":
        "application/x-www-form-urlencoded"
};


/* =========================================================
   DEBUG
   ========================================================= */

console.log(
    "========== CASE TOKEN REQUEST =========="
);

console.log(
    "URL:",
    bh.local.caseTokenUrl
);

console.log(
    "Body:",
    bh.local.caseTokenBody
);

console.log(
    "Headers:",
    JSON.stringify(
        bh.local.caseTokenHeaders,
        null,
        2
    )
);

console.log(
    "========================================="
);

/* =========================================================
   PREPARE CASE CREATION HTTP REQUEST
   ========================================================= */

if (
    !bh.local.caseAccessToken ||
    typeof bh.local.caseAccessToken !== "string" ||
    !bh.local.caseAccessToken.trim()
) {

    bh.local.caseCreationReady = false;

    console.error(
        "CASE CREATION STOPPED: access token missing."
    );

} else {

    /* =====================================================
       URL
       ===================================================== */

    const BASE_URL =
        bh.system.environment.CASE_SERVICE_BASE_URL;


    bh.local.caseCreationUrl =
        (BASE_URL || "").replace(/\/+$/, "") +
        "/caseservice/case/instance/create?branch=main";


    /* =====================================================
       HEADERS
       ===================================================== */

    bh.local.caseCreationHeaders = {

        "Authorization":
            "Bearer " +
            bh.local.caseAccessToken.trim(),

        "Content-Type":
            "application/json",

        "Accept":
            "application/json"
    };


    /* =====================================================
       BODY
       ===================================================== */

    bh.local.caseCreationBody =
        JSON.stringify(
            bh.local.caseCreationRequest
        );


    bh.local.caseCreationReady = true;


    /* =====================================================
       DEBUG
       ===================================================== */

    console.log(
        "========== CASE CREATION HTTP REQUEST =========="
    );

    console.log(
        "URL:",
        bh.local.caseCreationUrl
    );

    console.log(
        "Headers:",
        JSON.stringify(
            bh.local.caseCreationHeaders,
            null,
            2
        )
    );

    console.log(
        "Body:",
        bh.local.caseCreationBody
    );

    console.log(
        "Ready:",
        bh.local.caseCreationReady
    );

    console.log(
        "================================================="
    );
}

/* =========================================================
   CLAIM UPDATE SUCCESS
   ========================================================= */

console.log(
    "========== CLAIM UPDATE =========="
);

console.log(
    "Update SQL:",
    bh.local.updateSql
);

console.log(
    "Claim ID:",
    bh.local.claimId
);

console.log(
    "New Status:",
    bh.local.status
);


/*
 * SQL node completed without throwing an error.
 * Therefore the UPDATE was successful.
 */

bh.local.claimUpdateSuccess = true;


console.log(
    "claimUpdateSuccess:",
    bh.local.claimUpdateSuccess
);

console.log(
    "=================================="
);
